const meta=(a,lang='zh')=>{const g=grammar(),id=canonical(a),m=g.archetypes?.[id]||g.archetypes?.generic;if(!m)throw new Error(`unsupported signal archetype: ${id}`);return {...m,id,label:lang==='en'?(m.label_en||m.label):(m.label_zh||m.label)}};
const node=(nodes,i,fallback)=>nodes?.[i]||{label:fallback,summary:''};
